import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 140 He wants to know if ...","description":"学习 间接疑问句的陈述语序，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 140 He wants to know if ...","description":"学习 间接疑问句的陈述语序，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 间接疑问句的陈述语序，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 139 Is that you, John?","link":"/life/english/new-concept/book-1/unit-06/lesson-139"},"next":{"text":"第一册：英语初阶 · Lesson 141 Sally's first train ride","link":"/life/english/new-concept/book-1/unit-06/lesson-141"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 139 Is that you, John?","link":"/life/english/new-concept/book-1/unit-06/lesson-139"},"next":{"text":"第一册：英语初阶 · Lesson 141 Sally's first train ride","link":"/life/english/new-concept/book-1/unit-06/lesson-141"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-140.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-140.md"}`),i={name:"life/english/new-concept/book-1/unit-06/lesson-140.md"};function l(s,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-140-he-wants-to-know-if" tabindex="-1">第一册：英语初阶 · Lesson 140 He wants to know if ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-140-he-wants-to-know-if" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 140 He wants to know if ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-139">配套课 Lesson 139</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>转述电话里提出的问题 本课要掌握间接疑问句的陈述语序，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>extra</td><td>/ˈekstrə/</td><td>adj.</td><td>额外的</td><td>extra work</td></tr><tr><td>whether</td><td>/ˈweðə/</td><td>conj.</td><td>是否</td><td>ask whether</td></tr><tr><td>caller</td><td>/ˈkɔːlə/</td><td>n.</td><td>打电话者</td><td>an unknown caller</td></tr><tr><td>know</td><td>/nəʊ/</td><td>v.</td><td>知道</td><td>know the answer</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>wants to know if — 想知道是否</li><li>could you tell me — 礼貌询问信息</li></ul><h2 id="语法讲解-间接疑问句的陈述语序" tabindex="-1">语法讲解：间接疑问句的陈述语序 <a class="header-anchor" href="#语法讲解-间接疑问句的陈述语序" aria-label="Permalink to &quot;语法讲解：间接疑问句的陈述语序&quot;">​</a></h2><p>宾语从句中的疑问内容采用陈述语序：know where he lives，而非 know where does he live。一般疑问内容可用 if/whether 表“是否”；这里的 if 不表示条件。转述时去掉原问句帮助倒装的 do/does/did，但把所需时态保留在从句谓语。礼貌问句外层可以倒装，内层仍用陈述语序。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Could you tell me when the meeting starts?</p></blockquote><p>你能告诉我会议什么时候开始吗？</p><p>Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>从句写 when the meeting starts，不写 when does the meeting start。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Could you tell me when the meeting starts?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Could you tell me when the meeting starts? She wants to know whether the office is open.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“转述电话里提出的问题”写两至三句，再读给同伴听。至少使用一次间接疑问句的陈述语序，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。 Wants to know 是主句谓语结构；whether 表“是否”，从句 the office is open 采用陈述语序。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补“是否”：She asks ___ the office is open.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if / whether</p><p><strong>解析：</strong> 按本课规则判断：宾语从句中的疑问内容采用陈述语序：know where he lives，而非 know where does he live。一般疑问内容可用 if/whether 表“是否”；这里的 if 不表示条件。转述时去掉原问句帮助倒装的 do/does/did，但把所需时态保留在从句谓语。礼貌问句外层可以倒装，内层仍用陈述语序。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“你能告诉我会议什么时候开始吗？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Could you tell me when the meeting starts?</p><p><strong>解析：</strong> Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：She wants to know whether the office is open.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 她想知道办公室是否开门。</p><p><strong>解析：</strong> Wants to know 是主句谓语结构；whether 表“是否”，从句 the office is open 采用陈述语序。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接疑问句的陈述语序。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-139">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-141">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(i,[["render",l]]);export{p as __pageData,k as default};
